document.addEventListener('DOMContentLoaded', () => {
    const siteSelector = document.getElementById('site-selector');
    const imageUpload = document.getElementById('image-upload');
    const dropZone = document.getElementById('drop-zone');
    const downloadBtn = document.getElementById('download-btn');

    const cardTitlePreview = document.getElementById('card-title-preview');
    const cardPricePreview = document.getElementById('card-price-preview');
    const cardPriceContainer = document.getElementById('card-price-container');
    const cardColorHeader = document.getElementById('card-color-header');
    const cardImagePreview = document.getElementById('card-image-preview');
    const noImageText = document.getElementById('no-image-text');
    const specialFront = document.getElementById('special-front');
    const specialIcon = document.getElementById('special-icon');
    const specialTitle = document.getElementById('special-title');
    const specialSubtitle = document.getElementById('special-subtitle');
    const cardBackText = document.getElementById('card-back-text');
    const cardBackBorder = document.getElementById('card-back-border');
    const normalContainer = document.getElementById('card-back-normal-container');
    const policeContainer = document.getElementById('card-back-police-container');
    const stationTitle = document.getElementById('card-back-station-title');
    const logoTuareg = document.getElementById('card-back-logo-top');
    const busIcon = document.getElementById('card-back-bus-icon');

    const ICONOS = {
        'salida': `<svg class="special-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata> <path d="M20 100 L85 35 L85 72 L180 72 L180 128 L85 128 L85 165 Z" fill="#ED1B24" stroke="#000" stroke-width="7" stroke-linejoin="round"/> </svg>`,
        'parking': `<svg class="special-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata> <path d="M15 125 L15 105 Q15 95 28 92 L60 88 L80 60 Q85 55 95 55 L130 55 Q140 55 146 62 L162 88 L180 94 Q188 97 188 108 L188 125 Z" fill="#ED1B24" stroke="#000" stroke-width="6" stroke-linejoin="round"/> <path d="M88 64 L72 88 L112 88 L112 64 Z M122 64 L122 88 L152 88 L138 64 Z" fill="#fff" stroke="#000" stroke-width="4" stroke-linejoin="round"/> <circle cx="55" cy="128" r="20" fill="#222" stroke="#000" stroke-width="5"/> <circle cx="55" cy="128" r="8" fill="#ccc"/> <circle cx="150" cy="128" r="20" fill="#222" stroke="#000" stroke-width="5"/> <circle cx="150" cy="128" r="8" fill="#ccc"/> </svg>`,
        'suerte': `<svg class="special-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata> <path d="M60 70 C60 35 85 20 105 20 C135 20 152 40 152 65 C152 90 132 100 118 112 C108 120 106 128 106 140 L82 140 C82 118 90 106 106 94 C116 86 124 80 124 68 C124 56 116 48 104 48 C90 48 84 58 84 70 Z" fill="#F7941D" stroke="#000" stroke-width="7" stroke-linejoin="round"/> <circle cx="94" cy="170" r="16" fill="#F7941D" stroke="#000" stroke-width="7"/> </svg>`,
        'fontaneria': `<svg class="special-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata> <path d="M30 55 L30 35 L120 35 Q150 35 150 62 L150 78 L122 78 L122 64 Q122 62 120 62 L58 62 L58 55 Z" fill="#B0B7BD" stroke="#000" stroke-width="6" stroke-linejoin="round"/> <rect x="62" y="18" width="48" height="17" rx="4" fill="#ED1B24" stroke="#000" stroke-width="5"/> <rect x="116" y="78" width="40" height="22" rx="4" fill="#B0B7BD" stroke="#000" stroke-width="5"/> <path d="M136 112 C136 112 114 140 114 156 C114 170 124 180 136 180 C148 180 158 170 158 156 C158 140 136 112 136 112 Z" fill="#00AEEF" stroke="#000" stroke-width="6" stroke-linejoin="round"/> <path d="M126 152 Q126 164 136 168" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round"/> </svg>`,
        'electricidad': `<svg class="special-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata> <path d="M100 18 C65 18 42 44 42 76 C42 98 54 112 66 126 C72 134 74 140 74 148 L126 148 C126 140 128 134 134 126 C146 112 158 98 158 76 C158 44 135 18 100 18 Z" fill="#FFF200" stroke="#000" stroke-width="7" stroke-linejoin="round"/> <path d="M104 46 L82 90 L100 90 L92 122 L120 76 L102 76 Z" fill="#F7941D" stroke="#000" stroke-width="4" stroke-linejoin="round"/> <rect x="72" y="148" width="56" height="12" rx="3" fill="#B0B7BD" stroke="#000" stroke-width="5"/> <rect x="76" y="160" width="48" height="12" rx="3" fill="#B0B7BD" stroke="#000" stroke-width="5"/> <path d="M88 172 L112 172 L106 184 L94 184 Z" fill="#555" stroke="#000" stroke-width="5" stroke-linejoin="round"/> </svg>`,
        'impuesto-joyas': `<svg class="special-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata> <circle cx="100" cy="132" r="46" fill="none" stroke="#000" stroke-width="22"/> <circle cx="100" cy="132" r="46" fill="none" stroke="#FDB913" stroke-width="12"/> <path d="M72 50 L128 50 L148 76 L100 112 L52 76 Z" fill="#00AEEF" stroke="#000" stroke-width="6" stroke-linejoin="round"/> <path d="M52 76 L148 76 M72 50 L82 76 L100 112 L118 76 L128 50 M82 76 L100 50 L118 76" fill="none" stroke="#000" stroke-width="4" stroke-linejoin="round"/> </svg>`
    };

    const fallbackScript = document.getElementById('casillas-data');
    let datosCasillas = [];

    try {
        if (fallbackScript) {
            datosCasillas = JSON.parse(fallbackScript.textContent);
        } else {
            throw new Error('No hay datos incrustados en la página.');
        }
    } catch (error) {
        console.error('No se pudieron cargar los datos:', error);
        showMessage('No se pudieron cargar las casillas.');
        return;
    }

    datosCasillas.forEach((casilla) => {
        const option = document.createElement('option');
        option.value = casilla.id;
        option.textContent = casilla.nombre;
        siteSelector.appendChild(option);
    });

    siteSelector.addEventListener('change', (event) => {
        const seleccion = datosCasillas.find((casilla) => casilla.id === event.target.value);
        if (!seleccion) {
            return;
        }

        const esEspecial = seleccion.tipo === 'especial';
        dropZone.style.display = esEspecial ? 'none' : '';
        specialFront.classList.toggle('hidden', !esEspecial);
        cardImagePreview.style.visibility = esEspecial ? 'hidden' : 'visible';
        noImageText.classList.toggle('hidden', esEspecial);

        if (esEspecial) {
            const configuracionEspecial = {
                salida: { icono: ICONOS['salida'], titulo: 'CASILLA DE SALIDA', subtitulo: 'AVANZA Y COBRA 200€' },
                parking: { icono: ICONOS['parking'], titulo: 'PARKING GRATUITO', subtitulo: 'DESCANSO Y SUERTE' },
                suerte: { icono: ICONOS['suerte'], titulo: 'SUERTE', subtitulo: 'TOMA UNA CARTA' },
                fontaneria: { icono: ICONOS['fontaneria'], titulo: 'FONTANERÍA', subtitulo: 'SERVICIO DE AGUA' },
                electricidad: { icono: ICONOS['electricidad'], titulo: 'ELECTRICIDAD', subtitulo: 'SERVICIO ELÉCTRICO' },
                'impuesto-joyas': { icono: ICONOS['impuesto-joyas'], titulo: 'IMPUESTO JOYAS', subtitulo: 'PAGA 100€' }
            }[seleccion.especial];

            specialIcon.innerHTML = configuracionEspecial.icono;
            specialTitle.textContent = configuracionEspecial.titulo;
            specialSubtitle.textContent = configuracionEspecial.subtitulo;
        }

        cardTitlePreview.textContent = seleccion.nombre;
        const tienePalabraLarga = seleccion.nombre.split(' ').some((palabra) => palabra.length >= 10);
        cardTitlePreview.className = tienePalabraLarga
            ? 'monopoly-font font-bold text-xl sm:text-2xl text-center uppercase leading-tight text-white tracking-wide w-full'
            : 'monopoly-font font-bold text-2xl sm:text-3xl text-center uppercase leading-tight text-white tracking-widest w-full';

        cardColorHeader.style.backgroundColor = seleccion.color;
        const red = parseInt(seleccion.color.substr(1, 2), 16);
        const green = parseInt(seleccion.color.substr(3, 2), 16);
        const blue = parseInt(seleccion.color.substr(5, 2), 16);
        const yiq = ((red * 299) + (green * 587) + (blue * 114)) / 1000;
        cardTitlePreview.style.color = yiq >= 140 ? '#000000' : '#ffffff';

        if (seleccion.precio !== null) {
            cardPricePreview.textContent = `${seleccion.precio}€`;
            cardPriceContainer.style.display = 'flex';
        } else {
            cardPriceContainer.style.display = 'none';
        }

        if (seleccion.tipo === 'policia') {
            normalContainer.style.display = 'none';
            policeContainer.style.display = 'flex';
            cardBackBorder.style.backgroundColor = 'transparent';
        } else if (seleccion.tipo === 'estacion') {
            normalContainer.style.display = 'flex';
            policeContainer.style.display = 'none';
            stationTitle.style.display = 'block';
            logoTuareg.style.display = 'none';
            busIcon.style.display = 'block';
            cardBackText.textContent = 'RAFAL';
            cardBackText.className = 'monopoly-font font-bold text-4xl sm:text-5xl uppercase tracking-[0.15em] text-[#ed1b24]';
            cardBackBorder.style.backgroundColor = 'transparent';
        } else {
            normalContainer.style.display = 'flex';
            policeContainer.style.display = 'none';
            stationTitle.style.display = 'none';
            logoTuareg.style.display = 'block';
            busIcon.style.display = 'none';
            cardBackText.textContent = 'RAFAL';
            cardBackText.className = 'monopoly-font font-bold text-5xl sm:text-6xl uppercase tracking-[0.15em] text-[#ed1b24]';
            cardBackBorder.style.backgroundColor = 'transparent';
        }
    });

    const handleImage = (file) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onload = (event) => {
                cardImagePreview.src = event.target.result;
                noImageText.classList.add('hidden');
            };
            reader.readAsDataURL(file);
        } else {
            showMessage('Sube un archivo JPG o PNG válido.');
        }
    };

    imageUpload.addEventListener('change', (event) => handleImage(event.target.files[0]));

    dropZone.addEventListener('dragover', (event) => {
        event.preventDefault();
        dropZone.classList.add('border-red-500', 'bg-red-50');
    });

    dropZone.addEventListener('dragleave', () => {
        dropZone.classList.remove('border-red-500', 'bg-red-50');
    });

    dropZone.addEventListener('drop', (event) => {
        event.preventDefault();
        dropZone.classList.remove('border-red-500', 'bg-red-50');
        if (event.dataTransfer.files.length) {
            imageUpload.files = event.dataTransfer.files;
            handleImage(event.dataTransfer.files[0]);
        }
    });

    downloadBtn.addEventListener('click', async () => {
        if (!siteSelector.value) {
            showMessage('¡Selecciona una casilla primero!');
            return;
        }

        const cardElement = document.getElementById('monopoly-card');
        const cardBackElement = document.getElementById('monopoly-card-back');
        const originalText = downloadBtn.innerHTML;
        downloadBtn.innerHTML = '<svg class="animate-spin -ml-1 mr-3 h-5 w-5 text-white inline" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg> Generando PDF...';
        downloadBtn.disabled = true;

        try {
            const seleccion = datosCasillas.find((casilla) => casilla.id === siteSelector.value);
            const fileName = seleccion ? seleccion.nombre.replace(/\s+/g, '_').toLowerCase() : 'casilla';
            const canvasFront = await html2canvas(cardElement, { scale: 3, useCORS: true, backgroundColor: null });
            await new Promise((resolve) => setTimeout(resolve, 300));
            const canvasBack = await html2canvas(cardBackElement, { scale: 3, useCORS: true, backgroundColor: null });
            const { jsPDF } = window.jspdf;
            const pdf = new jsPDF({
                orientation: 'portrait',
                unit: 'px',
                format: [canvasFront.width, canvasFront.height]
            });

            pdf.addImage(canvasFront.toDataURL('image/png'), 'PNG', 0, 0, canvasFront.width, canvasFront.height);
            pdf.addPage();
            pdf.addImage(canvasBack.toDataURL('image/png'), 'PNG', 0, 0, canvasBack.width, canvasBack.height);
            pdf.save(`monopoly_rafal_${fileName}.pdf`);
        } catch (error) {
            console.error('Error:', error);
            showMessage('Hubo un error al generar el PDF.');
        } finally {
            downloadBtn.innerHTML = originalText;
            downloadBtn.disabled = false;
        }
    });

    function showMessage(message) {
        const toast = document.createElement('div');
        toast.className = 'fixed bottom-4 right-4 bg-gray-800 text-white px-6 py-3 rounded-lg shadow-lg z-50 transition-opacity duration-500';
        toast.textContent = message;
        document.body.appendChild(toast);
        setTimeout(() => {
            toast.style.opacity = '0';
            setTimeout(() => toast.remove(), 500);
        }, 3000);
    }
});
